}

/* Add a C null term string as bulk reply */
void addReplyBulkCString(client *c, const char *s) {
    if (s == NULL) {
        addReplyNull(c);
    } else {
        addReplyBulkCBuffer(c, s, strlen(s));
    }
}

/* Add a long long as a bulk reply */
void addReplyBulkLongLong(client *c, long long ll) {
    char buf[64];
    int len;

    len = ll2string(buf, 64, ll);
    addReplyBulkCBuffer(c, buf, len);
}

/* Add the shard reply of a single shard based off the given primary node. */
void addShardReplyForClusterShards(client *c, list *nodes) {
    serverAssert(nodes->len > 0);

    int prefix = c->resp == 2 ? '*' : '%';
    long map_len = 2;
    if (c->resp == 2) map_len *= 2;
    addReplyAggregateLen(c, map_len, prefix);
    addReplyBulkCString(c, "slots");

    listIter li;
    listRewind(nodes, &li);
    listNode *ln = li.next;
    serverAssert(ln == nodes->head);
    clusterNode *n = ln->value;

    /* Use slot_info_pairs from the primary only */
    n = clusterNodeGetPrimary(n);

    uint16_t *slot_pairs = clusterNodeGetSlotInfoPairs(n);
    int slot_pair_count = clusterNodeGetSlotInfoPairsCount(n);
    if (slot_pairs != NULL) {
        serverAssert((slot_pair_count % 2) == 0);
        addReplyArrayLen(c, slot_pair_count);
        for (int i = 0; i < slot_pair_count; i++) addReplyLongLong(c, (unsigned long)slot_pairs[i]);
    } else {
        /* If no slot info pair is provided, the node owns no slots */
        addReplyArrayLen(c, 0);
    }

    addReplyBulkCString(c, "nodes");
    addReplyArrayLen(c, nodes->len);
    ln = nodes->head;
    while (ln != NULL) {
        clusterNode *node = ln->value;
        addNodeDetailsToShardReply(c, node);
        clusterFreeNodesSlotsInfo(node);
        ln = ln->next;
    }
}

/* Reply with a verbatim type having the specified extension.
 *
 * The 'ext' is the "extension" of the file, actually just a three
 * character type that describes the format of the verbatim string.
 * For instance "txt" means it should be interpreted as a text only
 * file by the receiver, "md " as markdown, and so forth. Only the
 * three first characters of the extension are used, and if the
 * provided one is shorter than that, the remaining is filled with
 * spaces. */
void addReplyVerbatim(client *c, const char *s, size_t len, const char *ext) {
    if (c->resp == 2) {
        addReplyBulkCBuffer(c, s, len);
    } else {
        char buf[32];
        size_t preflen = snprintf(buf, sizeof(buf), "=%zu\r\nxxx:", len + 4);
        char *p = buf + preflen - 4;
        for (int i = 0; i < 3; i++) {
            if (*ext == '\0') {
                p[i] = ' ';
            } else {
                p[i] = *ext++;
            }
        }
        addReplyProto(c, buf, preflen);
        addReplyProto(c, s, len);
        addReplyProto(c, "\r\n", 2);
    }
}

